package dev.pocketengine.features.devices;

import java.nio.charset.StandardCharsets;
import java.security.Signature;
import java.security.cert.X509Certificate;
import java.security.interfaces.ECPublicKey;
import java.util.Base64;
import java.util.Set;
import org.json.JSONArray;
import org.json.JSONObject;

/** Standard P-256/SHA-256 signatures over bounded, attenuated delegation statements. */
public final class DelegationGrant {
    private DelegationGrant(){}
    private static final Set<String> FIELDS=DeviceProtocol.set("protocolVersion protocolProfile messageType issuerDeviceId delegateDeviceId targetResources rootTaskId parentTaskId grantId authorizationEpoch capabilities toolNames toolBudget modelBudget deadline remainingDepth previousProofDigest sourceAllocationId targetShares issuerCertificateDer issuerCertificateFingerprint signature");
    private static JSONObject unsigned(JSONObject signed)throws Exception{JSONObject value=new JSONObject(signed.toString());value.remove("signature");return value;}
    /** Native parent budget reservation MUST precede signing. A proof never allocates budget. */
    public static JSONObject sign(DeviceIdentity.LocalIdentity local,JSONObject statement)throws Exception{
        JSONObject value=PairingCoordinator.copy(statement);if(value.has("signature")||value.has("issuerCertificateDer")||value.has("issuerCertificateFingerprint"))throw new SecurityException("Native signer owns certificate and signature fields");
        if(!local.deviceId().equals(value.optString("issuerDeviceId")))throw new SecurityException("Delegation issuer does not own this key");
        value.put("issuerCertificateDer",Base64.getEncoder().encodeToString(local.certificateDer())).put("issuerCertificateFingerprint",local.certificateFingerprint());validateShape(value,false);
        value.put("signature",Base64.getEncoder().encodeToString(local.sign(DeviceProtocol.canonical(value).getBytes(StandardCharsets.UTF_8))));return value;
    }
    public static void validateTargetResources(JSONArray values){if(values==null||values.length()<1||values.length()>128)throw new SecurityException("Invalid exact forwarding target/resources");Set<String> seen=new java.util.HashSet<>();for(int i=0;i<values.length();i++){JSONObject pair=values.optJSONObject(i);DeviceProtocol.keys(pair,DeviceProtocol.set("targetDeviceId resourceBinding"),Set.of());DeviceProtocol.deviceId(pair.opt("targetDeviceId"),"targetDeviceId");if(pair.optJSONObject("resourceBinding")==null||!seen.add(DeviceProtocol.canonical(pair)))throw new SecurityException("Duplicate or invalid exact target/resource pair");}}
    public static boolean targetResourceContains(JSONArray values,String target,JSONObject binding){if(values!=null)for(int i=0;i<values.length();i++){JSONObject pair=values.optJSONObject(i);if(pair!=null&&target.equals(pair.opt("targetDeviceId"))&&DeviceProtocol.resourceEquals(binding,pair.optJSONObject("resourceBinding")))return true;}return false;}
    /** Stable source/target/resource correlation only, not a grant or a spend receipt. */
    public static String shareId(String issuer,String sourceAllocation,String target,JSONObject binding)throws Exception{
        if(binding==null)throw new SecurityException("Source share requires an exact resource");return "ds1_"+DeviceProtocol.sha256(DeviceProtocol.canonicalBytes(new JSONObject().put("protocolVersion",DeviceProtocol.VERSION).put("issuerDeviceId",DeviceProtocol.deviceId(issuer,"issuerDeviceId")).put("sourceAllocationId",DeviceProtocol.identifier(sourceAllocation,"sourceAllocationId")).put("targetDeviceId",DeviceProtocol.deviceId(target,"targetDeviceId")).put("resourceBinding",binding)));
    }
    public static JSONObject targetShare(String issuer,String sourceAllocation,String target,JSONObject binding,long tools,long models)throws Exception{return new JSONObject().put("shareId",shareId(issuer,sourceAllocation,target,binding)).put("targetDeviceId",target).put("resourceBinding",PairingCoordinator.copy(binding)).put("toolBudget",DeviceProtocol.integer(tools,"toolBudget",0,400)).put("modelBudget",DeviceProtocol.integer(models,"modelBudget",0,1000));}
    private static void validateShares(JSONObject proof)throws Exception{
        String source=DeviceProtocol.identifier(proof.opt("sourceAllocationId"),"sourceAllocationId");JSONArray shares=proof.optJSONArray("targetShares");if(shares==null||shares.length()<1||shares.length()>129)throw new SecurityException("Invalid signed source target shares");Set<String> seen=new java.util.HashSet<>();long tools=0,models=0;
        for(int i=0;i<shares.length();i++){JSONObject share=shares.optJSONObject(i);DeviceProtocol.keys(share,DeviceProtocol.set("shareId targetDeviceId resourceBinding toolBudget modelBudget"),Set.of());String expected=shareId(proof.getString("issuerDeviceId"),source,share.getString("targetDeviceId"),share.optJSONObject("resourceBinding"));if(!expected.equals(share.opt("shareId"))||!seen.add(expected))throw new SecurityException("Duplicate or changed source share identity");if(!proof.getString("delegateDeviceId").equals(share.optString("targetDeviceId"))&&!targetResourceContains(proof.getJSONArray("targetResources"),share.optString("targetDeviceId"),share.optJSONObject("resourceBinding")))throw new SecurityException("Share target outside signed route");if(!proof.getString("delegateDeviceId").equals(share.optString("targetDeviceId"))&&!targetResourceContains(proof.getJSONArray("targetResources"),share.optString("targetDeviceId"),share.optJSONObject("resourceBinding")))throw new SecurityException("Share expanded exact forwarding resource");tools+=DeviceProtocol.integer(share.opt("toolBudget"),"toolBudget",0,400);models+=DeviceProtocol.integer(share.opt("modelBudget"),"modelBudget",0,1000);}
        if(tools>proof.getLong("toolBudget")||models>proof.getLong("modelBudget"))throw new SecurityException("Source target shares exceed the one original reservation");
    }
    private static JSONObject matchingShare(JSONObject proof,String target,JSONObject binding)throws Exception{JSONObject found=null;JSONArray shares=proof.getJSONArray("targetShares");for(int i=0;i<shares.length();i++){JSONObject share=shares.getJSONObject(i);if(target.equals(share.getString("targetDeviceId"))&&DeviceProtocol.resourceEquals(binding,share.getJSONObject("resourceBinding"))){if(found!=null)throw new SecurityException("Duplicate source target share");found=share;}}if(found==null)throw new SecurityException("A did not sign this exact target/resource share");return found;}
    /** Metadata only after native Permission verified A; this method alone conveys no authority. */
    static JSONObject admittedSourceShare(DeviceTaskEnvelope request)throws Exception{JSONObject proof="task.submitGoal".equals(request.method())?request.arguments().optJSONObject("delegationAuthorization"):null;JSONArray chain=request.json().optJSONArray("delegationChain");if(proof==null&&chain!=null&&chain.length()>0)proof=chain.getJSONObject(0);if(proof==null)return null;return PairingCoordinator.copy(matchingShare(proof,request.targetDeviceId(),request.resourceBinding())).put("issuerDeviceId",proof.getString("issuerDeviceId")).put("sourceAllocationId",proof.getString("sourceAllocationId")).put("deadline",proof.getLong("deadline")).put("sourceGrantId",proof.getString("grantId")).put("sourceAuthorizationEpoch",proof.getLong("authorizationEpoch")).put("sourceProofFingerprint",DeviceProtocol.sha256(DeviceProtocol.canonicalBytes(unsigned(proof))));}
    private static void validateShape(JSONObject value,boolean signed)throws Exception{
        DeviceProtocol.requireProfile(value);Set<String> required=new java.util.HashSet<>(FIELDS);if(!signed)required.remove("signature");DeviceProtocol.keys(value,required,Set.of());
        if(!DeviceProtocol.VERSION.equals(value.opt("protocolVersion"))||!"DelegationProof".equals(value.opt("messageType")))throw new SecurityException("Unsupported delegation proof");
        for(String name:DeviceProtocol.set("issuerDeviceId delegateDeviceId"))DeviceProtocol.deviceId(value.opt(name),name);
        for(String name:DeviceProtocol.set("rootTaskId parentTaskId grantId"))DeviceProtocol.identifier(value.opt(name),name);
        for(String name:DeviceProtocol.set("authorizationEpoch deadline"))DeviceProtocol.integer(value.opt(name),name,1,DeviceProtocol.MAX_SAFE_INTEGER);
        DeviceProtocol.integer(value.opt("toolBudget"),"toolBudget",0,400);DeviceProtocol.integer(value.opt("modelBudget"),"modelBudget",0,1000);DeviceProtocol.integer(value.opt("remainingDepth"),"remainingDepth",0,2);
        String previous=value.optString("previousProofDigest");if(!(previous.isEmpty()||previous.matches("[a-f0-9]{64}")))throw new SecurityException("Invalid previous proof digest");
        if(!value.optString("issuerCertificateFingerprint").matches("[a-f0-9]{64}"))throw new SecurityException("Invalid issuer fingerprint");
        canonicalBase64(value.opt("issuerCertificateDer"),"issuerCertificateDer",64,16384,22000);if(signed)canonicalBase64(value.opt("signature"),"signature",8,80,200);
        JSONArray pairs=value.optJSONArray("targetResources");validateTargetResources(pairs);for(int i=0;i<pairs.length();i++){String target=pairs.optJSONObject(i).optString("targetDeviceId");if(target.equals(value.optString("issuerDeviceId"))||target.equals(value.optString("delegateDeviceId")))throw new SecurityException("Forwarding target scope creates a cycle");}
        for(String key:DeviceProtocol.set("capabilities toolNames")){JSONArray array=value.optJSONArray(key);if(array==null||array.length()>128||!"toolNames".equals(key)&&array.length()==0)throw new SecurityException("Invalid delegation scope");Set<String> seen=new java.util.HashSet<>();for(int i=0;i<array.length();i++){String item=DeviceProtocol.text(array.opt(i),key,128);if(!seen.add(item))throw new SecurityException("Duplicate delegation scope");}}
        validateShares(value);DeviceProtocol.canonical(value);
    }
    private static void canonicalBase64(Object value,String name,int minimum,int maximum,int maxText){String text=DeviceProtocol.text(value,name,maxText);try{byte[] bytes=Base64.getDecoder().decode(text);if(bytes.length<minimum||bytes.length>maximum||!Base64.getEncoder().encodeToString(bytes).equals(text))throw new IllegalArgumentException();}catch(Exception invalid){throw new SecurityException("Invalid canonical base64 "+name);}}
    /** Closed signed shape only. Real signature/current receiving grants are checked separately. */
    public static void validateWireProof(JSONObject proof){try{validateShape(proof,true);}catch(DeviceProtocol.ProtocolException invalid){throw invalid;}catch(Exception invalid){throw DeviceProtocol.fail("invalid_request","Invalid signed delegation proof shape");}}
    public static void validateForwardingScope(JSONObject scope){
        DeviceProtocol.keys(scope,DeviceProtocol.set("targetResources capabilities toolNames toolBudget modelBudget maxDelegationDepth"),Set.of());
        if(DeviceProtocol.integer(scope.opt("maxDelegationDepth"),"maxDelegationDepth",2,2)!=2)throw new SecurityException("Forwarding is limited to the second device edge");
        DeviceProtocol.integer(scope.opt("toolBudget"),"toolBudget",0,400);DeviceProtocol.integer(scope.opt("modelBudget"),"modelBudget",0,1000);
        validateTargetResources(scope.optJSONArray("targetResources"));for(String name:DeviceProtocol.set("capabilities toolNames")){JSONArray values=scope.optJSONArray(name);if(values==null||values.length()>128||!"toolNames".equals(name)&&values.length()==0)throw new SecurityException("Invalid explicit forwarding scope");Set<String> seen=new java.util.HashSet<>();for(int i=0;i<values.length();i++){String value=DeviceProtocol.text(values.opt(i),name,128);if(!seen.add(value))throw new SecurityException("Duplicate forwarding scope");}}
        DeviceProtocol.canonical(scope);
    }
    /** Validate A's initial, explicitly owner-bounded proof BEFORE B accepts its goal. */
    public static JSONObject verifyForwardingAuthorization(DeviceIdentity.AuthenticatedPeer peer,DeviceTaskEnvelope goal,JSONObject receivingGrant,long now)throws Exception{
        JSONObject proof=goal.arguments().optJSONObject("delegationAuthorization");if(proof==null)return null;JSONObject scope=receivingGrant.optJSONObject("forwardingScope");validateForwardingScope(scope);validateShape(proof,true);
        JSONArray visited=goal.json().optJSONArray("visitedDevices");if(!"task.submitGoal".equals(goal.method())||!goal.originDeviceId().equals(goal.callerDeviceId())||visited!=null&&visited.length()!=1||goal.json().optInt("maxDelegationDepth",2)!=2)throw new SecurityException("Initial forwarding proof can authorize only A to B to one final device");
        verifySigner(proof,goal.originDeviceId(),now);if(!peer.certificateFingerprint().equals(proof.optString("issuerCertificateFingerprint"))||!goal.targetDeviceId().equals(proof.optString("delegateDeviceId"))||!goal.rootTaskId().equals(proof.optString("rootTaskId"))||!DeviceProtocol.receiverTaskId(goal).equals(proof.optString("parentTaskId"))||!goal.grantId().equals(proof.optString("grantId"))||goal.authorizationEpoch()!=proof.optLong("authorizationEpoch")||!proof.optString("previousProofDigest").isEmpty()||proof.optInt("remainingDepth")!=0)throw new SecurityException("Initial forwarding proof changed its exact accepted parent or grant");
        if(proof.optLong("deadline")>Math.min(goal.deadline(),receivingGrant.optLong("expiresAt"))||proof.optLong("deadline")<=now||proof.optLong("toolBudget")>goal.budget().optLong("toolCalls")||proof.optLong("modelBudget")>goal.budget().optLong("modelCalls")||!proof.optString("sourceAllocationId").equals(goal.budget().optString("allocationId")))throw new SecurityException("Initial forwarding proof expanded task limits");
        JSONObject localShare=matchingShare(proof,goal.targetDeviceId(),goal.resourceBinding());long forwardedTools=0,forwardedModels=0;for(int i=0;i<proof.getJSONArray("targetShares").length();i++){JSONObject share=proof.getJSONArray("targetShares").getJSONObject(i);if(goal.targetDeviceId().equals(share.getString("targetDeviceId"))){if(!DeviceProtocol.resourceEquals(localShare.getJSONObject("resourceBinding"),share.getJSONObject("resourceBinding")))throw new SecurityException("A signed an unbound delegate resource");}else{forwardedTools+=share.getLong("toolBudget");forwardedModels+=share.getLong("modelBudget");}}if(forwardedTools>scope.getLong("toolBudget")||forwardedModels>scope.getLong("modelBudget"))throw new SecurityException("Forwarded shares expanded B owner forwarding scope");
        for(String name:DeviceProtocol.set("targetResources capabilities toolNames"))if(!subset(proof.getJSONArray(name),scope.getJSONArray(name)))throw new SecurityException("Initial forwarding proof expanded owner scope");
        for(int i=0;i<proof.getJSONArray("targetResources").length();i++){String target=proof.getJSONArray("targetResources").getJSONObject(i).getString("targetDeviceId");if(target.equals(goal.originDeviceId())||target.equals(goal.targetDeviceId()))throw new SecurityException("Initial forwarding proof creates a device cycle");}
        for(int i=0;i<proof.getJSONArray("targetShares").length();i++){JSONObject share=proof.getJSONArray("targetShares").getJSONObject(i);if(!share.getString("targetDeviceId").equals(goal.targetDeviceId())&&!targetResourceContains(scope.getJSONArray("targetResources"),share.getString("targetDeviceId"),share.getJSONObject("resourceBinding")))throw new SecurityException("A share expanded B owner exact target/resource pair");}
        return PairingCoordinator.copy(proof);
    }
    private static X509Certificate verifySigner(JSONObject proof,String expectedIssuer,long now)throws Exception{
        X509Certificate certificate=DeviceIdentity.certificate(Base64.getDecoder().decode(proof.getString("issuerCertificateDer")));certificate.checkValidity(new java.util.Date(now));if(!DeviceIdentity.id(certificate).equals(expectedIssuer)||!proof.getString("issuerDeviceId").equals(expectedIssuer)||!DeviceProtocol.sha256(certificate.getEncoded()).equals(proof.getString("issuerCertificateFingerprint")))throw new SecurityException("Delegation signer does not match the original route");DeviceIdentity.verifySignature(certificate,DeviceProtocol.canonicalBytes(unsigned(proof)),Base64.getDecoder().decode(proof.getString("signature")));return certificate;
    }
    public static void verify(DeviceTaskEnvelope request,JSONObject receivingGrant,long now)throws Exception{
        JSONArray chain=request.json().optJSONArray("delegationChain"),visited=request.json().optJSONArray("visitedDevices");
        if(!receivingGrant.optBoolean("allowDelegation")||chain==null||visited==null||chain.length()<1||chain.length()!=visited.length()-1||visited.length()>receivingGrant.optInt("maxDelegationDepth"))throw new SecurityException("Receiver did not grant this delegation route");
        JSONObject previous=null;
        for(int i=0;i<chain.length();i++){
            JSONObject proof=chain.getJSONObject(i);validateShape(proof,true);verifySigner(proof,visited.getString(i),now);if(!proof.getString("delegateDeviceId").equals(visited.getString(i+1)))throw new SecurityException("Delegation signer does not match the original route");
            if(!targetResourceContains(proof.getJSONArray("targetResources"),request.targetDeviceId(),request.resourceBinding())||!proof.getString("rootTaskId").equals(request.rootTaskId())||!PairingCoordinator.contains(proof.getJSONArray("capabilities"),request.method())||proof.getLong("deadline")<request.deadline()||proof.getLong("deadline")<=now||proof.getInt("remainingDepth")<chain.length()-i-1)throw new SecurityException("Delegation does not authorize this request");
            if("tool.invoke".equals(request.method())&&!PairingCoordinator.contains(proof.getJSONArray("toolNames"),request.toolInvocation().toolName()))throw new SecurityException("Delegated tool is not granted");
            JSONObject share=matchingShare(proof,request.targetDeviceId(),request.resourceBinding());if(!targetResourceContains(proof.getJSONArray("targetResources"),request.targetDeviceId(),request.resourceBinding())||request.budget().optLong("toolCalls")>share.getLong("toolBudget")||request.budget().optLong("modelCalls")>share.getLong("modelBudget"))throw new SecurityException("Delegated request exceeds A non-overlapping exact target share");
            String expected=previous==null?"":DeviceProtocol.sha256(DeviceProtocol.canonical(previous).getBytes(StandardCharsets.UTF_8));if(!expected.equals(proof.getString("previousProofDigest")))throw new SecurityException("Delegation proof chain changed");
            if(previous!=null){for(String scope:DeviceProtocol.set("targetResources capabilities toolNames"))if(!subset(proof.getJSONArray(scope),previous.getJSONArray(scope)))throw new SecurityException("Delegation scope expanded");if(proof.getLong("deadline")>previous.getLong("deadline")||proof.getLong("toolBudget")>previous.getLong("toolBudget")||proof.getLong("modelBudget")>previous.getLong("modelBudget")||proof.getInt("remainingDepth")>=previous.getInt("remainingDepth"))throw new SecurityException("Delegation limits expanded");}
            previous=proof;
        }
        if(previous==null||!previous.getString("parentTaskId").equals(request.parentTaskId()))throw new SecurityException("Delegation parent task changed");
    }
    private static boolean subset(JSONArray child,JSONArray parent){java.util.Set<String> allowed=new java.util.HashSet<>();for(int i=0;i<parent.length();i++)allowed.add(DeviceProtocol.canonical(parent.opt(i)));for(int i=0;i<child.length();i++)if(!allowed.contains(DeviceProtocol.canonical(child.opt(i))))return false;return true;}
}
